using System;using System.Linq;using System.Drawing;using System.Windows.Forms;
namespace BeamScheduleFormatter {
static class AngleQuantityBasis {
 internal static double RequiredPieces(double length,int quantity){SteelWeight.Positive(length);SteelWeight.Count(quantity);return length*quantity/6;}
 internal static double PaintingArea(SteelProfile profile,double length,int quantity){SteelWeight.Positive(length,profile.H,profile.B);SteelWeight.Count(quantity);return 2*(profile.H+profile.B)/1000*length*quantity;}
}
partial class ProgramOfWorksForm {
 void ConfigureAngleQuantityView(){string[] names={"AngleRequiredPieces","AngleRequiredTotalPieces","AngleInstalledLength","AngleNetWeight","AngleStocksOpened","AngleFinalOffcut","AnglePaintArea"};string[] captions={"Required pcs per item (6 m)","Required total pcs equivalent","Installed total length m","Installed net weight kg","New 6 m stocks opened pcs","Final reusable offcut m","Painting reference area m2"};for(int n=0;n<names.Length;n++){int status=steelAngles.Columns.Count-1;var column=new DataGridViewTextBoxColumn{Name=names[n],HeaderText=captions[n],ReadOnly=true,Width=160};steelAngles.Columns.Insert(status,column);}steelAngles.Columns["AngleRequiredPieces"].ToolTipText="Entered item length / 6. Example 10.322m = 1.72 pcs equivalent per item; whole purchase is separate.";steelAngles.Columns["AngleStocksOpened"].ToolTipText="Whole stocks opened for this row; compatible rows can use their leftovers without opening another stock.";steelAngles.Columns["AnglePaintArea"].ToolTipText="Installed length only × 2(H+B)/1000: all longitudinal faces of an ideal angle. No offcuts or end caps included.";}
 void UpdateAngleQuantityView(){foreach(DataGridViewRow row in steelAngles.Rows){var demand=row.Tag as SteelCutDemand;if(demand==null)continue;var profile=FindSteelProfile(Cell(row,2));if(profile==null)continue;var opened=steelStocks.Where(stock=>stock.Cuts.Count>0&&object.ReferenceEquals(stock.Cuts[0].Demand.Source??stock.Cuts[0].Demand,demand)).ToList();row.Cells["AngleRequiredPieces"].Value=AngleQuantityBasis.RequiredPieces(demand.Length,1);row.Cells["AngleRequiredTotalPieces"].Value=AngleQuantityBasis.RequiredPieces(demand.Length,demand.Quantity);row.Cells["AngleInstalledLength"].Value=demand.Length*demand.Quantity;row.Cells["AngleNetWeight"].Value=demand.Length*demand.Quantity*demand.KgM;row.Cells["AngleStocksOpened"].Value=opened.Count;row.Cells["AngleFinalOffcut"].Value=opened.Sum(s=>s.Remaining);row.Cells["AnglePaintArea"].Value=AngleQuantityBasis.PaintingArea(profile,demand.Length,demand.Quantity);foreach(string name in new[]{"AngleRequiredPieces","AngleRequiredTotalPieces","AngleNetWeight","AnglePaintArea"})row.Cells[name].Style.Format="0.00";foreach(string name in new[]{"AngleInstalledLength","AngleFinalOffcut"})row.Cells[name].Style.Format="0.000";}}
 double AnglePaintingTotal(){return steelAngles.Rows.Cast<DataGridViewRow>().Where(r=>!r.IsNewRow&&r.Tag is SteelCutDemand&&r.Cells["AnglePaintArea"].Value!=null).Sum(r=>Convert.ToDouble(r.Cells["AnglePaintArea"].Value));}
}
}
